      <div className="size-2 rounded-full border border-foreground/5 bg-muted-foreground/10" />
      <div className="size-2 rounded-full border border-foreground/5 bg-muted-foreground/10" />
      <div className="size-2 rounded-full border border-foreground/5 bg-muted-foreground/10" />
    </div>
    <CodeBlock
      code={PHP_CODE}
      lang="php"
      maxHeight={300}
      theme={theme || "github-light"}
